def choose_move(observation):
    def clamp(v):
        if v < -1:
            return -1
        if v > 1:
            return 1
        return v

    def sign(x):
        if x > 0:
            return 1
        if x < 0:
            return -1
        return 0

    def is_pair(x):
        return isinstance(x, (list, tuple)) and len(x) >= 2 and isinstance(x[0], (int, float)) and isinstance(x[1], (int, float))

    def get_me(obs):
        for k in ("position", "pos", "agent_pos", "self_pos", "loc", "location", "xy"):
            v = obs.get(k)
            if is_pair(v):
                return v[0], v[1]
        for k in ("agents", "players", "units"):
            v = obs.get(k, [])
            if isinstance(v, list) and v:
                first = v[0]
                if isinstance(first, dict):
                    for pk in ("position", "pos", "loc", "location", "xy"):
                        p = first.get(pk)
                        if is_pair(p):
                            return p[0], p[1]
                elif is_pair(first):
                    return first[0], first[1]
        return 0, 0

    def extract_points(val):
        pts = []
        if isinstance(val, dict):
            for v in val.values():
                pts.extend(extract_points(v))
        elif isinstance(val, list):
            for item in val:
                if is_pair(item):
                    pts.append((item[0], item[1]))
                elif isinstance(item, dict):
                    pts.extend(extract_points(item))
                elif isinstance(item, list):
                    pts.extend(extract_points(item))
        return pts

    def all_points(obs):
        pts = []
        for k in ("resources", "resource_positions", "resource_tiles", "food", "targets",
                  "enemies", "enemy_positions", "opponents", "enemy_units",
                  "territories", "territory", "control_points", "bases", "flags",
                  "points", "objects", "entities", "grid"):
            v = obs.get(k)
            if v is not None:
                pts.extend(extract_points(v))
        return pts

    def nearest(points, x, y):
        best = None
        best_d = None
        for px, py in points:
            d = abs(px - x) + abs(py - y)
            if best_d is None or d < best_d:
                best_d = d
                best = (px, py)
        return best, best_d

    x, y = get_me(observation)
    dx = 0
    dy = 0

    # Gather useful point sets defensively.
    resources = []
    enemies = []
    territory_targets = []
    for k in ("resources", "resource_positions", "resource_tiles", "food"):
        resources.extend(extract_points(observation.get(k)))
    for k in ("enemies", "enemy_positions", "opponents", "enemy_units"):
        enemies.extend(extract_points(observation.get(k)))
    for k in ("territories", "territory", "control_points", "bases", "flags"):
        territory_targets.extend(extract_points(observation.get(k)))

    # Also scan generic containers.
    if not resources:
        pts = all_points(observation)
        # split generic points by semantic hints if possible
        if pts:
            resources = pts[:]
    # Prefer action based on likely game mode.
    mode = observation.get("mode")
    if mode == "resource_collection" or resources:
        target, _ = nearest(resources, x, y)
        if target is not None:
            tx, ty = target
            dx = sign(tx - x)
            dy = sign(ty - y)
    elif mode == "pursuit_evasion" or enemies:
        # Chase if stronger/closer; otherwise evade nearest.
        me_power = observation.get("power", observation.get("strength", 0))
        enemy_power = observation.get("enemy_power", None)
        target, dist = nearest(enemies, x, y)
        if target is not None:
            tx, ty = target
            if enemy_power is not None and isinstance(enemy_power, (int, float)) and me_power >= enemy_power:
                dx = sign(tx - x)
                dy = sign(ty - y)
            else:
                dx = sign(x - tx)
                dy = sign(y - ty)
        else:
            dx = 0
            dy = 0
    elif mode == "territory_control" or territory_targets:
        target, _ = nearest(territory_targets, x, y)
        if target is not None:
            tx, ty = target
            dx = sign(tx - x)
            dy = sign(ty - y)
    else:
        # Fallback: move toward any visible point, else a deterministic patrol.
        pts = all_points(observation)
        target, _ = nearest(pts, x, y)
        if target is not None:
            tx, ty = target
            dx = sign(tx - x)
            dy = sign(ty - y)
        else:
            t = observation.get("turn", observation.get("step", 0))
            if isinstance(t, int):
                if t % 4 == 0:
                    dx, dy = 1, 0
                elif t % 4 == 1:
                    dx, dy = 0, 1
                elif t % 4 == 2:
                    dx, dy = -1, 0
                else:
                    dx, dy = 0, -1

    return [clamp(dx), clamp(dy)]

